1	// Package store keeps Tally's data in memory. It is safe for concurrent use.
2	//
3	// Every object belongs to one organization. Methods that take an orgID only ever see that organization's objects; the few
4	// methods that find an object by ID alone (CustomerByID, InvoiceByID, EventByID) are for background jobs and the admin
5	// tool, which act on behalf of the system rather than a member.
6	package store
7	
8	import (
9		"crypto/rand"
10		"encoding/hex"
11		"errors"
12		"fmt"
13		"sort"
14		"strings"
15		"sync"
16		"time"
17	)
18	
19	// Errors. Callers check them with errors.Is; most are wrapped with a detail.
20	var (
21		ErrNotFound      = errors.New("not found")
22		ErrInvalid       = errors.New("invalid")
23		ErrConflict      = errors.New("conflict")
24		ErrEmailTaken    = fmt.Errorf("%w: email address already in use", ErrConflict)
25		ErrAlreadyMember = fmt.Errorf("%w: already a member", ErrConflict)
26		// ErrCustomerOrgMismatch is returned when an object names a customer of another organization.
