// Package money handles amounts of money. An amount is an int64 count of its currency's minor unit (cents for USD), never a
// float.
package money

import (
	"errors"
	"fmt"
	"strconv"
	"strings"
)

// Currency is an ISO 4217 currency code.
type Currency string

// The currencies Tally bills in.
const (
	USD Currency = "USD"
	EUR Currency = "EUR"
	GBP Currency = "GBP"
	JPY Currency = "JPY"
	KWD Currency = "KWD"
)

var symbols = map[Currency]string{USD: "$", EUR: "€", GBP: "£", JPY: "¥", KWD: "KWD "}

// Valid reports whether c is a currency Tally bills in.
func (c Currency) Valid() bool {
	_, ok := symbols[c]
	return ok
}

// ErrInvalidAmount is returned for an amount that cannot be read.
var ErrInvalidAmount = errors.New("invalid amount")

// ParseMajor reads an amount a person typed in major units ("12.50", "7") and returns it in minor units.
func ParseMajor(s string, c Currency) (int64, error) {
	if !c.Valid() {
		return 0, fmt.Errorf("%w: unknown currency %q", ErrInvalidAmount, c)
	}
	s = strings.TrimSpace(s)
	whole, frac, hasDot := strings.Cut(s, ".")
	if whole == "" || (hasDot && frac == "") || len(frac) > 2 {
		return 0, fmt.Errorf("%w: %q", ErrInvalidAmount, s)
	}
	for _, r := range whole + frac {
		if r < '0' || r > '9' {
			return 0, fmt.Errorf("%w: %q", ErrInvalidAmount, s)
		}
	}
	for len(frac) < 2 {
		frac += "0"
	}
	n, err := strconv.ParseInt(whole+frac, 10, 64)
	if err != nil {
		return 0, fmt.Errorf("%w: %q", ErrInvalidAmount, s)
	}
	return n, nil
}

// Format renders an amount for people: "$1,234.50", "-€0.99".
func Format(amount int64, c Currency) string {
	sign := ""
	if amount < 0 {
		sign, amount = "-", -amount
	}
	whole, frac := amount/100, amount%100
	return fmt.Sprintf("%s%s%s.%02d", sign, symbols[c], group(whole), frac)
}

// group writes n with a comma between each group of three digits.
func group(n int64) string {
	s := strconv.FormatInt(n, 10)
	var b strings.Builder
	for i, r := range s {
		if i > 0 && (len(s)-i)%3 == 0 {
			b.WriteByte(',')
		}
		b.WriteRune(r)
	}
	return b.String()
}

// Percent returns pct percent of amount, rounded half away from zero to a whole minor unit.
func Percent(amount int64, pct int) int64 { return divRound(amount*int64(pct), 100) }

// BasisPoints returns bp basis points (hundredths of a percent) of amount, rounded half away from zero.
func BasisPoints(amount int64, bp int) int64 { return divRound(amount*int64(bp), 10000) }

// divRound divides and rounds half away from zero.
func divRound(num, den int64) int64 {
	if (num < 0) != (den < 0) {
		return -((abs(num) + abs(den)/2) / abs(den))
	}
	return (abs(num) + abs(den)/2) / abs(den)
}

func abs(v int64) int64 {
	if v < 0 {
		return -v
	}
	return v
}
// Package payments charges invoices through the payment gateway.
package payments

import (
	"context"
	"errors"
	"fmt"

	"example.com/tally/internal/billing"
	"example.com/tally/internal/clock"
	"example.com/tally/internal/money"
	"example.com/tally/internal/store"
)

// ChargeRequest asks the gateway to take money from a payment method.
type ChargeRequest struct {
	Amount        int64 // minor units
	Currency      money.Currency
	PaymentMethod string // "pm_..."
	Description   string
}

// ChargeResult is a successful charge.
type ChargeResult struct {
	Ref string // the gateway's reference, "ch_..."
}

// Gateway is the payment processor.
type Gateway interface {
	Charge(ctx context.Context, req ChargeRequest) (ChargeResult, error)
}

// DeclineError is a charge the card's issuer refused. Nothing was taken.
type DeclineError struct {
	Code string // for example "card_declined", "insufficient_funds"
}

func (e *DeclineError) Error() string { return "card declined: " + e.Code }

// Errors.
var (
	// ErrUnavailable means the gateway could not be reached or failed; nothing was taken and the charge may be retried.
	ErrUnavailable     = errors.New("payment gateway unavailable")
	ErrAlreadyPaid     = errors.New("the invoice is already paid")
	ErrInvoiceVoid     = errors.New("the invoice is void")
	ErrNoPaymentMethod = errors.New("no payment method to charge")
)

// Publisher sends events to the organization's webhook endpoints (webhooks.Service).
type Publisher interface {
	Publish(ctx context.Context, orgID, eventType string, data any) error
}

// Service pays invoices.
type Service struct {
	Store     *store.Store
	Gateway   Gateway
	Clock     clock.Clock
	Publisher Publisher // nil: no events
}

// Pay charges an open invoice's total to paymentMethod, or to the customer's default payment method when it is empty, and
// marks the invoice paid. An invoice whose total is zero or less is marked paid without a charge. A declined charge is
// recorded as a failed payment and returned as a *DeclineError; when the gateway is unavailable nothing is recorded and the
// error wraps ErrUnavailable.
func (s *Service) Pay(ctx context.Context, orgID, invoiceID, paymentMethod string) (store.Invoice, store.Payment, error) {
	inv, ok := s.Store.Invoice(orgID, invoiceID)
	if !ok {
		return store.Invoice{}, store.Payment{}, store.ErrNotFound
	}
	switch inv.Status {
	case store.InvoicePaid:
		return inv, store.Payment{}, ErrAlreadyPaid
	case store.InvoiceVoid:
		return inv, store.Payment{}, ErrInvoiceVoid
	}
	total := billing.Compute(inv).Total
	if total <= 0 {
		inv, err := s.markPaid(ctx, inv, store.Payment{})
		return inv, store.Payment{}, err
	}
	if paymentMethod == "" {
		if c, ok := s.Store.Customer(orgID, inv.CustomerID); ok {
			paymentMethod = c.DefaultPaymentMethod
		}
	}
	if paymentMethod == "" {
		return inv, store.Payment{}, ErrNoPaymentMethod
	}
	res, err := s.Gateway.Charge(ctx, ChargeRequest{Amount: total, Currency: inv.Currency, PaymentMethod: paymentMethod, Description: "Invoice " + inv.ID})
	var decline *DeclineError
	switch {
	case errors.As(err, &decline):
		p, perr := s.Store.CreatePayment(store.Payment{OrgID: orgID, InvoiceID: inv.ID, Amount: total, Currency: inv.Currency, Status: store.PaymentFailed, FailureCode: decline.Code}, s.Clock.Now())
		if perr != nil {
			return inv, store.Payment{}, perr
		}
		s.publish(ctx, orgID, "invoice.payment_failed", map[string]any{"invoice_id": inv.ID, "payment_id": p.ID, "failure_code": decline.Code})
		return inv, p, err
	case err != nil:
		if errors.Is(err, ErrUnavailable) {
			return inv, store.Payment{}, err
		}
		return inv, store.Payment{}, fmt.Errorf("%w: %v", ErrUnavailable, err)
	}
	p, err := s.Store.CreatePayment(store.Payment{OrgID: orgID, InvoiceID: inv.ID, Amount: total, Currency: inv.Currency, Status: store.PaymentSucceeded, GatewayRef: res.Ref}, s.Clock.Now())
	if err != nil {
		return inv, store.Payment{}, err
	}
	inv, err = s.markPaid(ctx, inv, p)
	return inv, p, err
}

func (s *Service) markPaid(ctx context.Context, inv store.Invoice, p store.Payment) (store.Invoice, error) {
	now := s.Clock.Now()
	inv, err := s.Store.UpdateInvoice(inv.OrgID, inv.ID, func(i *store.Invoice) error {
		i.Status = store.InvoicePaid
		i.PaidAt = &now
		return nil
	})
	if err != nil {
		return store.Invoice{}, err
	}
	s.publish(ctx, inv.OrgID, "invoice.paid", map[string]any{"invoice_id": inv.ID, "payment_id": p.ID, "amount": p.Amount, "currency": inv.Currency})
	return inv, nil
}

func (s *Service) publish(ctx context.Context, orgID, typ string, data any) {
	if s.Publisher != nil {
		_ = s.Publisher.Publish(ctx, orgID, typ, data)
	}
}
// Package snapshot saves the store to a JSON file and loads it back, so the server keeps its data across restarts. The
// file carries a version; files written by older versions of Tally are migrated when they are loaded.
package snapshot

import (
	"encoding/json"
	"errors"
	"fmt"
	"os"
	"time"

	"example.com/tally/internal/money"
	"example.com/tally/internal/store"
)

// Version is the version Save writes.
const Version = 2

// ErrUnsupportedVersion is returned for a file of a version Load cannot read.
var ErrUnsupportedVersion = errors.New("unsupported snapshot version")

type fileV2 struct {
	Version int         `json:"version"`
	SavedAt time.Time   `json:"saved_at"`
	State   store.State `json:"state"`
}

// Save writes everything in st to path.
func Save(st *store.Store, path string, now time.Time) error {
	b, err := json.MarshalIndent(fileV2{Version: Version, SavedAt: now.UTC(), State: st.Export()}, "", "  ")
	if err != nil {
		return err
	}
	return os.WriteFile(path, append(b, '\n'), 0o600)
}

// Load reads a snapshot written by Save, or by an older version of Tally, and returns a store holding it.
func Load(path string) (*store.Store, error) {
	b, err := os.ReadFile(path)
	if err != nil {
		return nil, err
	}
	var head struct {
		Version int `json:"version"`
	}
	if err := json.Unmarshal(b, &head); err != nil {
		return nil, fmt.Errorf("snapshot %s: %w", path, err)
	}
	var st store.State
	switch head.Version {
	case 1:
		if st, err = migrateV1(b); err != nil {
			return nil, fmt.Errorf("snapshot %s: version 1: %w", path, err)
		}
	case 2:
		var f fileV2
		if err := json.Unmarshal(b, &f); err != nil {
			return nil, fmt.Errorf("snapshot %s: %w", path, err)
		}
		st = f.State
	default:
		return nil, fmt.Errorf("snapshot %s: %w %d", path, ErrUnsupportedVersion, head.Version)
	}
	return store.FromState(st)
}

// Version 1 (Tally 0.x) kept the state at the top level. Organizations had no plan or time zone, customers had a
// full_name, and plans had a price in US cents (price_cents) and were all licensed.
type fileV1 struct {
	Seq           int                  `json:"seq"`
	Orgs          []orgV1              `json:"orgs"`
	Users         []store.User         `json:"users"`
	Members       []store.Member       `json:"members"`
	APIKeys       []store.APIKey       `json:"api_keys"`
	Customers     []customerV1         `json:"customers"`
	Plans         []planV1             `json:"plans"`
	Subscriptions []store.Subscription `json:"subscriptions"`
	Invoices      []store.Invoice      `json:"invoices"`
	Payments      []store.Payment      `json:"payments"`
}

type orgV1 struct {
	ID        string    `json:"id"`
	Name      string    `json:"name"`
	TaxRateBP int       `json:"tax_rate_bp"`
	CreatedAt time.Time `json:"created_at"`
}

type customerV1 struct {
	ID        string    `json:"id"`
	OrgID     string    `json:"org_id"`
	FullName  string    `json:"full_name"`
	Email     string    `json:"email"`
	CreatedAt time.Time `json:"created_at"`
}

type planV1 struct {
	ID         string         `json:"id"`
	OrgID      string         `json:"org_id"`
	Name       string         `json:"name"`
	PriceCents int64          `json:"price_cents"`
	Interval   store.Interval `json:"interval"`
	TrialDays  int            `json:"trial_days"`
	CreatedAt  time.Time      `json:"created_at"`
}

func migrateV1(b []byte) (store.State, error) {
	var f fileV1
	if err := json.Unmarshal(b, &f); err != nil {
		return store.State{}, err
	}
	st := store.State{Seq: f.Seq, Users: f.Users, Members: f.Members, APIKeys: f.APIKeys, Subscriptions: f.Subscriptions, Invoices: f.Invoices, Payments: f.Payments}
	for _, o := range f.Orgs {
		st.Orgs = append(st.Orgs, store.Org{ID: o.ID, Name: o.Name, Plan: store.OrgFree, TimeZone: "UTC", TaxRateBP: o.TaxRateBP, CreatedAt: o.CreatedAt})
	}
	for _, c := range f.Customers {
		st.Customers = append(st.Customers, store.Customer{ID: c.ID, OrgID: c.OrgID, Name: c.FullName, Email: c.Email, CreatedAt: c.CreatedAt})
	}
	for _, p := range f.Plans {
		st.Plans = append(st.Plans, store.Plan{ID: p.ID, OrgID: p.OrgID, Name: p.Name, Currency: money.USD, UnitAmount: p.PriceCents, Interval: p.Interval,
			UsageType: store.Licensed, TrialDays: p.TrialDays, Active: true, CreatedAt: p.CreatedAt})
	}
	return st, nil
}

